mapper.update:

UPDATE ICOMCART SET
    CART_QTY    = #{CART_QTY}
WHERE BUYER     = #{st_wms_code}
	AND USER_ID = #{USER_ID}
    AND CONTRACT_NO     = #{CONTRACT_NO}
    AND CONTRACT_SEQ    = #{CONTRACT_SEQ}
    AND USE_FLAG	    = #{USE_FLAG}


UPDATE WMSSTCK SET 
	PRE_GR_QTY = PRE_GR_QTY + TO_NUMBER(#{CART_QTY})
WHERE WAREHOUSE_CODE = #{st_wms_code}
	AND STDCATLG_ID = #{BUYER_ITEM_NO}



			AND AGENT = 'KRKORE0001'	


			AND AGENT = #{AGENT}


UPDATE ICOMCQDT SET
    PO_QTY = NVL(PO_QTY,0) + TO_NUMBER(#{CART_QTY}),
    LAST_PO_PRICE = #{LIST_PRICE},
    LAST_PO_QTY = #{CART_QTY},
    LAST_PO_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
WHERE BUYER = #{st_wms_code}
    AND CONTRACT_NO =  #{CONTRACT_NO}
    AND CONTRACT_SEQ = #{CONTRACT_SEQ}


DELETE FROM ICOMCART  
WHERE BUYER = #{st_wms_code}
	AND USER_ID = #{USER_ID}
    AND CONTRACT_NO = #{CONTRACT_NO}
    AND CONTRACT_SEQ = #{CONTRACT_SEQ}
    AND USE_FLAG = #{USE_FLAG}

INSERT INTO ICOMPRDT ( BUYER, PR_NO, PR_SEQ, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, BUYER_ITEM_NO, SELLER_ITEM_NO, SELLER, CATALOG_ITEM_NO, ITEM_TYPE, DESCRIPTION, SPECIFICATION, HS_NO, MAKER_CODE, MAKER_NAME, MAKER_PART_NO, IMAGE_KEY, UNIT_MEASURE, CUR, RD_DATE, TARGET_PRICE, TARGET_QTY, DELY_TO_LOCATION, ACCOUNT_TYPE, RECV_FLAG, PURCHASING_AGENT_FLAG, PO_QTY, RETURN_REASON, REMARK, RFQ_NO, RFQ_COUNT, RFQ_SEQ, SAMPLE_FLAG, COMPLETE_MARK, RECV_QTY, GR_QTY, CTR_QTY, PURCHASER_ID, SUB_PURCHASER_ID, PURCHASER_DEPT, SAVE_FLAG, ADD_USER_ID, ADD_USER_NAME, ADD_USER_TEL, ADD_USER_DEPT, CHANGE_USER_ID, CHANGE_USER_NAME, CHANGE_USER_TEL, CHANGE_USER_DEPT, REF_NO, REF_SEQ, REF_PR_NO, REF_ADD_USER_ID, REQ_USER_ID, REQ_DEPT, AGENT, CONTRACT_NO, CONTRACT_SEQ, LEGACY_PO_NO, LEGACY_PO_SEQ, REF_IF_NO, LIST_PRICE, DOC_TYPE, REQ_USER_INFO, PLAN_AMT_FLAG, BYIT_COMORG_CODE, PROCESS_TYPE, CATEG_ID ) ( SELECT CA.BUYER AS BUYER, --//구매사(WAREHOUSE_CODE) #{st_pr_no} AS PR_NO, TO_CHAR(ROWNUM,'FM000000') AS PR_SEQ, 'R' AS STATUS, TO_CHAR(SYSDATE,'YYYYMMDD') AS ADD_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS ADD_TIME, TO_CHAR(SYSDATE,'YYYYMMDD') AS CHANGE_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS CHANGE_TIME, CA.BUYER_ITEM_NO AS BUYER_ITEM_NO, --//제품코드 CQ.SELLER_ITEM_NO AS SELLER_ITEM_NO, CQ.SELLER AS SELLER, CQ.CATALOG_ITEM_NO AS CATALOG_ITEM_NO, CQ.ITEM_TYPE AS ITEM_TYPE, CQ.DESCRIPTION AS DESCRIPTION, CQ.SPECIFICATION AS SPECIFICATION, CQ.HS_NO AS HS_NO, CQ.MAKER_CODE AS MAKER_CODE, CQ.MAKER_NAME AS MAKER_NAME, CQ.MAKER_PART_NO AS MAKER_PART_NO, '' AS IMAGE_KEY, CQ.UNIT_MEASURE AS UNIT_MEASURE, CQ.CUR AS CUR, #{st_rd_date} AS RD_DATE, DECODE(BT.FIXED_PRICE_FLAG, 'N', NVL(CA.UNIT_PRICE, 0), NVL(CQ.TARGET_PRICE, 0)) AS TARGET_PRICE, --//단가 CA.CART_QTY AS TARGET_QTY, --//수량 #{st_location_code} AS DELY_TO_LOCATION, CQ.ACCOUNT_TYPE AS ACCOUNT_TYPE, #{st_recv_flag} AS RECV_FLAG, 'N' AS PURCHASING_AGENT_FLAG, CA.CART_QTY AS PO_QTY, --//수량 '' AS RETURN_REASON, '' AS REMARK, '' AS RFQ_NO, '' AS RFQ_COUNT, '' AS RFQ_SEQ, 'N' AS SAMPLE_FLAG, '' AS COMPLETE_MARK, CA.CART_QTY AS RECV_QTY, 0 AS GR_QTY, 0 AS CTR_QTY, #{st_purchaser_id} AS PURCHASER_ID, '' AS SUB_PURCHASER_ID, #{st_purchase_dept} AS PURCHASER_DEPT, 'PX' AS SAFE_FLAG, CA.USER_ID AS ADD_USER_ID, --//요청자 (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS ADD_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS ADD_USER_TEL, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS ADD_USER_DEPT, CA.USER_ID AS CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS CHANGE_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS CHANGE_USER_TEL, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS CHANGE_USER_DEPT, '' AS REF_NO, '' AS REF_SEQ, CA.REF_PR_NO AS REF_PR_NO, --//관리번호(REF_PR_NO) '' AS REF_ADD_USER_ID, CA.USER_ID AS REQ_USER_ID, --//REQ_USER_ID ( SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS REQ_DEPT, CA.AGENT AS AGNET, CQ.CONTRACT_NO AS CONTRACT_NO, CQ.CONTRACT_SEQ AS CONTRACT_SEQ, #{st_pr_no} AS LEGACY_PO_NO, TO_CHAR(ROWNUM,'FM000000') AS LEGACY_PO_SEQ, '' AS REF_IF_NO, DECODE(BT.FIXED_PRICE_FLAG, 'N', NVL(CA.UNIT_PRICE, 0), NVL(CQ.LIST_PRICE, 0)) AS LIST_PRICE, --//단가 '' AS DOC_TYPE, '' AS REQ_USER_INFO, ( SELECT C.FLAG FROM ICOMCOD2 C WHERE C.TYPE='Z014' AND C.COMPANY_CODE = CA.BUYER AND C.CODE = CQ.ACCOUNT_TYPE ) AS PLAN_AMT_FLAG, CA.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, CQ.PROCESS_TYPE AS PROCESS_TYPE, BT.CATEGORY_NO AS CATEG_ID FROM ICOMCART CA, ICOMCQDT CQ, ICOMBYIT BT WHERE CA.USE_FLAG = 'C' AND CA.BYIT_COMORG_CODE = BT.BUYER AND CA.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND CQ.BUYER = BT.BUYER AND CQ.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND CA.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND CA.CONTRACT_NO = CQ.CONTRACT_NO AND CA.CONTRACT_SEQ = CQ.CONTRACT_SEQ AND BT.STATUS <> 'D' AND CQ.STATUS <> 'D' AND CA.BUYER = #{st_buyer} AND CA.USER_ID||CA.BUYER_ITEM_NO||CA.CONTRACT_NO||CA.CONTRACT_SEQ IN
#{item}
)

INSERT INTO ICOMPRHD ( BUYER, PR_NO, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, NOTIFY, PR_SUBJECT, PURCHASER_DEPT, RECV_FLAG, RETURN_REASON, ACCOUNT_TYPE, INVESTMENT_NO, SAMPLE_FLAG, DELY_TO_LOCATION, REMARK, ADD_USER_ID, ADD_USER_NAME, ADD_USER_TEL, ADD_USER_DEPT, CHANGE_USER_ID, CHANGE_USER_NAME, CHANGE_USER_TEL, CHANGE_USER_DEPT, SIGN_DATE, SIGN_PERSON_ID, SAVE_FLAG, IMAGE_KEY, DOC_TYPE ) ( SELECT CA.BUYER AS BUYER, #{st_pr_no} AS PR_NO, 'C' AS STATUS, TO_CHAR(SYSDATE,'YYYYMMDD') AS ADD_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS ADD_TIME, TO_CHAR(SYSDATE,'YYYYMMDD') AS CHANGE_DATE, TO_CHAR(SYSDATE,'HH24MISS') AS CHANGE_TIME, CA.BUYER AS NOTIFY, '*' AS PR_SUBJECT, #{st_purchase_dept} AS PURCHASER_DEPT, #{st_recv_flag} AS RECV_FLAG, '' AS RETURN_REASON, MAX(CQ.ACCOUNT_TYPE) AS ACCOUNT_TYPE, '*' AS INVESTMENT_NO, 'N' AS SAMPLE_FLAG, MAX((SELECT MAX(TEXT2) FROM ICOMCOD2 WHERE COMPANY_CODE=#{st_buyer} AND TYPE='C012' )) AS DELY_TO_LOCATION, #{st_remark} AS REMARK, CA.USER_ID AS ADD_USER_ID, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = CA.USER_ID)) AS ADD_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS ADD_USER_TEL, MAX((SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CA.USER_ID)) AS ADD_USER_DEPT, CA.USER_ID AS CHANGE_USER_ID, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = CA.USER_ID)) AS CHANGE_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = CA.USER_ID) AS CHANGE_USER_TEL, MAX((SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CA.USER_ID)) AS CHANGE_USER_DEPT, '' AS SIGN_DATE, '' AS SIGN_PERSON_ID, 'PX' AS SAVE_FLAG, '' AS IMAGE_KEY, #{st_gr_flag} AS DOC_TYPE FROM ICOMCART CA, ICOMCQDT CQ WHERE CA.USE_FLAG = 'C' AND CA.BYIT_COMORG_CODE = CQ.BUYER AND CA.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND CA.CONTRACT_NO = CQ.CONTRACT_NO AND CA.CONTRACT_SEQ = CQ.CONTRACT_SEQ AND CQ.STATUS <> 'D' AND CA.BUYER = #{st_buyer} AND CA.USER_ID||CA.BUYER_ITEM_NO||CA.CONTRACT_NO||CA.CONTRACT_SEQ IN
#{item}
GROUP BY CA.BUYER, CA.USER_ID )

DELETE FROM ICOMCART WHERE BUYER||USER_ID||CONTRACT_NO||CONTRACT_SEQ||USE_FLAG||BUYER_ITEM_NO||SEQ||BYIT_COMORG_CODE IN ( SELECT CA.BUYER||CA.USER_ID||CA.CONTRACT_NO||CA.CONTRACT_SEQ||CA.USE_FLAG||CA.BUYER_ITEM_NO||CA.SEQ||CA.BYIT_COMORG_CODE FROM ICOMCART CA, ICOMCQDT CQ WHERE CA.USE_FLAG = 'C' AND CA.BYIT_COMORG_CODE = CQ.BUYER AND CA.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND CA.CONTRACT_NO = CQ.CONTRACT_NO AND CA.CONTRACT_SEQ = CQ.CONTRACT_SEQ AND CQ.STATUS <> 'D' AND CA.BUYER = #{st_buyer} AND CA.USER_ID||CA.BUYER_ITEM_NO||CA.CONTRACT_NO||CA.CONTRACT_SEQ IN
#{item}
)

INSERT INTO EDIVPODT ( BUYER, VPO_NO, VPO_SEQ, AGENT, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, BUYER_ITEM_NO, DESCRIPTION, SPECIFICATION, UNIT_MEASURE, ITEM_QTY, UNIT_PRICE, ITEM_AMT, RD_DATE, MAKER_CODE, MAKER_NAME, DELY_TO_LOCATION, ORIGIN_CODE, IV_QTY, GR_QTY, VPO_DATE, VIV_DATE, VGR_DATE, RECV_FLAG, VPO_REMARK, POK_USER_ID, RECV_USER_ID, CONTRACT_NO, CONTRACT_SEQ ) ( SELECT CART.BUYER, #{st_po_no} AS VPO_NO, ROWNUM AS VPO_SEQ, CART.AGENT, 'C' AS STATUS, TO_CHAR(SYSDATE, 'YYYYMMDD') ADD_DATE, TO_CHAR(SYSDATE, 'HH24MISS') ADD_TIME, TO_CHAR(SYSDATE, 'YYYYMMDD') CH_DATE, TO_CHAR(SYSDATE, 'HH24MISS') CH_TIME, CART.BUYER_ITEM_NO, CQDT.DESCRIPTION AS DESCRIPTION, CQDT.SPECIFICATION AS SPECIFICATION, CQDT.UNIT_MEASURE AS UNIT_MEASURE, CART_QTY, CART.UNIT_PRICE, CART.CART_QTY * CART.UNIT_PRICE AS ITEM_AMT, #{st_rd_date} AS RD_DATE, CQDT.MAKER_CODE AS MAKER_CODE, CQDT.MAKER_NAME AS MAKER_NAME, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = CART.USER_ID) AS DELAY_TO_LOCATION, CQDT.ORIGIN_CODE AS ORGIN_CODE, 0 AS IV_QTY, 0 AS GR_QTY, TO_CHAR(SYSDATE,'YYYYMMDD') AS V_PO_DATE, '' AS VIV_DATE, '' AS VGR_DATE, 'A' AS RECV_FLAG, '' AS VPO_REMARK, #{st_user_id} AS POK_USER_ID, '' AS RECV_USER_ID, CART.CONTRACT_NO, CART.CONTRACT_SEQ FROM ICOMCART CART, ICOMCQDT CQDT WHERE CART.BUYER = CQDT.BUYER AND CART.CONTRACT_NO = CQDT.CONTRACT_NO AND CART.CONTRACT_SEQ = CQDT.CONTRACT_SEQ AND CART.BUYER = #{st_buyer} AND CQDT.STATUS ^='D' AND CQDT.PROCESS_TYPE = '3' AND CART.USER_ID||CQDT.BUYER_ITEM_NO||CQDT.CONTRACT_NO||CQDT.CONTRACT_SEQ IN
#{item}
)
